-- EximNext Thailand Suppliers Data Import
-- Generated by insert_data.py

CREATE DATABASE IF NOT EXISTS shop_ai;
USE shop_ai;

CREATE TABLE IF NOT EXISTS suppliers (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    rating DECIMAL(3,2) DEFAULT 3.00,
    reliable BOOLEAN DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS products (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    weight_kg DECIMAL(10,2) DEFAULT 1.00,
    selling_price_mmk DECIMAL(15,2) DEFAULT 0.00
);

CREATE TABLE IF NOT EXISTS supplier_products (
    id INT AUTO_INCREMENT PRIMARY KEY,
    supplier_id INT NOT NULL,
    product_id INT NOT NULL,
    price_thb DECIMAL(15,2) DEFAULT 100.00,
    moq INT DEFAULT 1,
    FOREIGN KEY (supplier_id) REFERENCES suppliers(id),
    FOREIGN KEY (product_id) REFERENCES products(id)
);

CREATE TABLE IF NOT EXISTS shipping_methods (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    cost_thb_per_kg DECIMAL(10,2) DEFAULT 50.00,
    delivery_days INT DEFAULT 7
);

